        let k = create__mmask32_from(0x55555555u32);
        let masked = unpack__m256i_to_u8_array(_mm256_mask_avg_epu8(src, k, a, b));
        let plain = unpack__m256i_to_u8_array(_mm256_avg_epu8(a, b));
